// Field Guide cards first taught in the 8 camp (Camp III): the web. HTML, CSS, browser JavaScript.
// Accuracy rule: describe what real browsers actually do. Shortcuts and platform details live in `os`.

export const GUIDE_CAMP8 = {
  // ─────────────── HTML: the bones ───────────────
  html: {
    term: 'HTML', stands: 'HyperText Markup Language',
    short: 'The text file that tells a browser what is on a page: headings, paragraphs, links, images, buttons.',
    what: 'HTML is the language every web page is written in. It is plain text with **tags** wrapped around the content, like `<h1>Camp III</h1>`, that tell the browser what each piece *is*: a heading, a paragraph, a link, a picture, a button.\n\n"HyperText" means text with links that jump to other pages. "Markup" means you *mark up* ordinary text with labels. HTML is not a programming language: it has no variables, no if/else, no loops. It only describes **structure**. CSS adds the looks and JavaScript adds the behaviour.',
    how: 'A browser downloads the HTML file, reads it top to bottom, and builds the page from it.\n\nA page has three layers: **HTML is the skeleton** (what exists and in what order), **CSS is the clothing** (colours, sizes, layout) and **JavaScript is the muscles** (what happens when you tap).\n\nOne big difference from JavaScript: **HTML never crashes**. A JavaScript syntax error stops your whole program. A broken HTML tag doesn\'t: the browser quietly guesses what you meant and carries on. That helps, but it means mistakes hide. The page *looks* nearly right while the structure underneath is wrong.\n\nHTML files end in `.html`. Open one in a browser and you see the page; open it in an editor and you see the tags.',
    usage: [
      { code: '<!doctype html>\n<html lang="en">\n  <head>\n    <meta charset="utf-8">\n    <title>Camp III</title>\n  </head>\n  <body>\n    <h1>Camp III</h1>\n    <p>7,200 metres. Rest here before the Yellow Band.</p>\n  </body>\n</html>', out: '(a page with a big bold heading "Camp III" and a line of text under it; the tab says "Camp III")', note: 'A complete, valid page. You\'ll learn every line of it this camp.' },
      { code: '<p>Pack your <strong>crampons</strong> and <a href="gear.html">see the gear list</a>.</p>', out: 'Pack your crampons and see the gear list.', note: '"crampons" shows bold, "see the gear list" is a clickable link to gear.html.' },
      { code: '<p>Unclosed <strong>bold text\n<p>Next paragraph</p>', out: '(both paragraphs show in bold)', note: 'No error message. The browser guessed the bold never ended, so it kept going.' },
    ],
    uses: ['Every web page you have ever opened, from a news site to a bank.', 'Web apps: even big interactive apps start as an HTML page that JavaScript then fills in.', 'Emails with formatting are HTML under the hood.', 'Docs and help pages, often written in simpler formats that get turned into HTML.'],
    when: ['You want something to show up in a browser.', 'You are describing *what* content is: "this is the main heading," "this is a list," "this is a button."'],
    whenNot: ['For looks. Don\'t pick `<h1>` because you want big text, or `<b>` sprinkled everywhere for style. Choose tags by meaning and use CSS for appearance.', 'For logic. HTML can\'t add numbers or make decisions; that is JavaScript\'s job.', 'Don\'t trust "it looks fine" as proof the HTML is correct. The browser hides your mistakes. Check the structure in the devtools.'],
    mistakes: [
      { wrong: '<p>Rope <strong>40 metres\n<p>Ice screws</p>', result: '(everything after "Rope" turns bold, including the next paragraph)', why: 'The `<strong>` was never closed with `</strong>`. HTML doesn\'t error; it just keeps the tag open. Close every tag you open.' },
      { prose: 'Leaving off `<!doctype html>` at the top.', why: 'The browser switches to "quirks mode," an old compatibility mode that copies 1990s browser bugs. Sizes and spacing can come out subtly wrong. Always start with the doctype.' },
      { prose: 'Double-clicking a `.html` file and being surprised it opens in a browser, not an editor.', why: 'That\'s the browser doing its job: showing the page. To change the tags, open the file in your code editor instead.' },
    ],
    tips: ['To see any page\'s HTML, add `view-source:` in front of its address (works in desktop Chrome and Firefox, and in Chrome on Android).', 'Write the closing tag right after the opening one, then fill in the middle. You\'ll never forget to close.', 'Indent nested tags by two spaces so you can see what\'s inside what.'],
    related: ['html-element', 'html-attribute', 'page-structure', 'css', 'dom'],
    os: {
      linux: 'Open a local page from the terminal: `xdg-open index.html` (opens it in your default browser). Or drag the file onto a browser window.',
      mac: 'Open a local page from the terminal: `open index.html`. Or drag the file onto a browser window.',
      windows: 'In WSL (Ubuntu), `explorer.exe index.html` opens it in your Windows browser. From Windows itself, double-click the file or run `start index.html` in PowerShell.',
      chromeos: 'Files you make in the Linux environment live in "Linux files" in the Files app. Double-click an `.html` file there to open it in Chrome.',
      phone: 'Phones can\'t easily open a local `.html` file. In this game the live preview plays the browser for you. On Chrome for Android you can still type `view-source:` before any address to read a real site\'s HTML.',
    },
  },
  'html-element': {
    term: 'HTML element (tags)', short: 'One piece of a page: an opening tag, the content, and a closing tag.',
    what: 'An **element** is one building block of a page. Most are written as an **opening tag**, some content, then a **closing tag** with a slash: `<p>Hello</p>`. The tag name (`p`) says what kind of element it is. The element is the whole thing: tags plus everything between them.',
    how: '**Anatomy:** `<h1>Camp III</h1>` is `<h1>` (opening tag) + `Camp III` (content) + `</h1>` (closing tag).\n\n**Nesting:** elements go inside other elements, like boxes in boxes. They must close in reverse order: last opened, first closed. `<p><strong>Hi</strong></p>` is right; `<p><strong>Hi</p></strong>` is tangled.\n\n**Void (empty) elements** have no content and no closing tag: `<img>`, `<br>`, `<hr>`, `<input>`, `<meta>`, `<link>`. Writing `<img … />` with a slash is allowed but optional.\n\n**Block vs inline:** block elements (`<h1>`–`<h6>`, `<p>`, `<div>`, `<ul>`, `<li>`, `<section>`) start on a new line and stretch the full width. Inline elements (`<a>`, `<strong>`, `<em>`, `<span>`, `<img>`) sit inside a line of text.\n\n**The ones you\'ll use most:**\n• `<h1>`…`<h6>` headings, biggest to smallest\n• `<p>` paragraph\n• `<a>` link (anchor)\n• `<img>` image\n• `<ul>` bullet list, `<ol>` numbered list, `<li>` list item\n• `<button>` a button\n• `<strong>` important (bold), `<em>` emphasis (italic)\n• `<div>` and `<span>` meaningless boxes, for when nothing else fits',
    usage: [
      { code: '<h2>Gear</h2>\n<ul>\n  <li>Rope</li>\n  <li>Ice axe</li>\n</ul>', out: 'Gear\n• Rope\n• Ice axe', note: 'A heading, then a bullet list. `<li>` items live inside the `<ul>`.' },
      { code: '<p>Line one<br>Line two</p>', out: 'Line one\nLine two', note: '`<br>` is a void element: a line break with no closing tag.' },
      { code: '<ol>\n  <li>Base Camp</li>\n  <li>Camp I</li>\n</ol>', out: '1. Base Camp\n2. Camp I', note: '`<ol>` numbers the items for you.' },
      { code: '<button>Pack it</button>', out: '(a clickable button labelled "Pack it")', note: 'A real button: it can be tapped, clicked, or pressed with the keyboard.' },
    ],
    uses: ['Every visible thing on a page is an element: headings, text, lists, pictures, buttons, inputs.', 'Lists of anything (menus, search results, gear) are `<ul>`/`<ol>` with `<li>` items.', 'Links between pages are `<a>` elements; that\'s what makes it the *web*.'],
    when: ['Pick the element whose **meaning** matches the content: a list is a `<ul>`, a heading is an `<h2>`, something you click to do an action is a `<button>`.'],
    whenNot: ['Don\'t reach for `<div>` and `<span>` first. They mean nothing to screen readers or search engines. Use them only when no meaningful element fits.', 'Don\'t use headings to make text big, or `<br><br><br>` to make space. That\'s styling: use CSS.', 'Don\'t make a fake button out of a `<div>`. It looks the same but can\'t be reached with the keyboard (see Accessibility).'],
    mistakes: [
      { wrong: '<p><strong>Summit</p></strong>', result: '(the browser untangles it its own way; the DOM may not match what you meant)', why: 'Tags must close in reverse order. Close `</strong>` before `</p>`.' },
      { wrong: '<p>Notes: <div>rope</div></p>', result: '(the browser ends the paragraph before the div, then adds an extra empty paragraph)', why: 'A `<p>` can\'t contain block boxes like `<div>`. The browser closes the `<p>` early, and the stray `</p>` becomes a second, empty `<p>`. Use a `<span>` inside a paragraph, or close the paragraph first.' },
      { wrong: '<img src="tent.png"></img>', result: '(the stray </img> is ignored)', why: '`<img>` is a void element: it never has a closing tag. Just write `<img src="tent.png" alt="…">`.' },
      { wrong: '<li>Rope</li> (with no <ul> around it)', result: '(it shows, but it isn\'t really a list)', why: '`<li>` belongs inside `<ul>` or `<ol>`. Screen readers announce "list, 3 items" only when the structure is right.' },
    ],
    tips: ['If you can\'t name what a box *means*, it\'s probably a `<div>`. If you can, there\'s probably a better tag.', 'Tag names are case-insensitive, but everyone writes them lowercase. Do the same.', 'Look at the Elements panel in the devtools to see how the browser actually nested your tags.'],
    related: ['html', 'html-attribute', 'page-structure', 'accessibility'],
  },
  'html-attribute': {
    term: 'HTML attribute', short: 'Extra settings written inside an opening tag: name="value".',
    what: 'An **attribute** adds information to an element. It goes inside the **opening tag**, written `name="value"`. For example, a link needs to know where it goes: `<a href="gear.html">Gear</a>`. Here `href` is the attribute name and `gear.html` is its value.',
    how: 'An element can have many attributes, separated by spaces, in any order. Put values in double quotes.\n\n**The attributes you\'ll use most:**\n• `href` on `<a>`: where the link goes\n• `src` on `<img>`: which image file to show\n• `alt` on `<img>`: text that replaces the image for people who can\'t see it\n• `id`: a **unique** name for one element on the page (only one element may have each id)\n• `class`: a **reusable** label; many elements can share a class, and one element can have several (`class="item packed"`)\n• `type` on `<input>` and `<button>`: what kind it is\n• `lang` on `<html>`: the page\'s language\n\n**Boolean attributes** are on just by being there: `<button disabled>`, `<input required>`, `<input type="checkbox" checked>`. Their value doesn\'t matter. Even `disabled="false"` still disables, because the attribute is present.\n\nYou can invent your own data attributes as long as they start with `data-`: `<li data-weight="2">`.',
    usage: [
      { code: '<a href="https://example.com/weather">Weather</a>', out: '(a link reading "Weather" that opens that address)', note: '`href` holds the address.' },
      { code: '<img src="tent.png" alt="Orange tent pitched on snow">', out: '(the picture; if it fails to load, the alt text shows instead)', note: '`src` = which file; `alt` = the words that stand in for it.' },
      { code: '<p id="status" class="note warning">Wind picking up</p>', note: 'One unique id, two classes. CSS and JavaScript can find it by either.' },
      { code: '<button disabled>Summit push</button>', out: '(a greyed-out button that can\'t be clicked)', note: 'A boolean attribute: present means on.' },
    ],
    uses: ['Links and images can\'t work without them (`href`, `src`).', '`id` and `class` are the handles CSS and JavaScript use to grab elements.', '`alt`, `lang` and `for` (on labels) make pages accessible.', 'Form settings: `type="email"`, `required`, `placeholder`, `name`.'],
    when: ['An element needs extra information to do its job: where to go, what to show, what kind it is.', 'You need a handle for CSS or JavaScript to find an element.'],
    whenNot: ['Don\'t reuse an `id`. If two elements share one, JavaScript\'s `querySelector` finds only the first, and labels connect to the wrong thing. Use a `class` for groups.', 'Don\'t put styling in attributes when CSS can do it. The old `<font color="red">` and `bgcolor` attributes are obsolete.', 'Don\'t write `disabled="false"` to switch something on. Remove the attribute entirely.'],
    mistakes: [
      { wrong: '<a>Gear list</a>', result: '(plain text that looks like a link but goes nowhere; it may not even be underlined)', why: 'Without `href`, an `<a>` isn\'t a working link. Add `href="gear.html"`.' },
      { wrong: '<button disabled="false">Go</button>', result: '(the button is still disabled)', why: 'For boolean attributes, presence is all that counts. Delete `disabled` to enable it.' },
      { wrong: '<img src="Tent.PNG"> (file is tent.png)', result: '(broken image icon on a real server)', why: 'Web servers are usually case-sensitive, like Linux. Match the file name exactly.' },
      { wrong: '<p class="note" class="big">', result: '(only class="note" is kept)', why: 'An attribute may appear once per element; the duplicate is ignored. Put several classes in one: `class="note big"`.' },
    ],
    tips: ['Always quote attribute values. Unquoted values break as soon as they contain a space.', 'Name ids and classes in lowercase-with-dashes: `packing-list`, `item-rope`.', 'Ids are for one-of-a-kind things (`#count`); classes are for kinds of things (`.item`).'],
    related: ['html-element', 'html', 'css-selector', 'accessibility', 'query-selector'],
  },
  'page-structure': {
    term: 'Page structure (head, body, landmarks)', short: 'The standard skeleton of a page, plus meaningful regions like header, nav, main and footer.',
    what: 'Every HTML page has the same basic skeleton: a **doctype**, an `<html>` element containing a `<head>` (information *about* the page) and a `<body>` (what you actually see). Inside the body, **semantic** elements like `<header>`, `<nav>`, `<main>` and `<footer>` mark out the regions of the page.',
    how: '**The skeleton, line by line:**\n• `<!doctype html>`: "this is modern HTML" (keeps the browser out of quirks mode)\n• `<html lang="en">`: the root; `lang` tells screen readers and translators which language to use\n• `<head>`: not shown on the page. Holds `<meta charset="utf-8">` (how to decode letters), `<meta name="viewport" …>` (how to size on phones), `<title>` (the browser tab text) and `<link>` for CSS files\n• `<body>`: everything visible\n\n**Landmarks** (semantic regions):\n• `<header>`: the top: site name, logo, maybe the nav\n• `<nav>`: the main menu of links\n• `<main>`: the main content. **Exactly one per page.**\n• `<section>`: a themed chunk, usually with its own heading\n• `<article>`: something that stands alone (a post, a trail report)\n• `<aside>`: side content (tips, related links)\n• `<footer>`: the bottom: credits, contact, small print\n\n**Headings form an outline:** one `<h1>` for the page title, `<h2>` for sections, `<h3>` for sub-sections. Don\'t skip levels.\n\nWhy bother? They look exactly like `<div>`s on screen. But screen reader users can jump straight to "main" or list every heading, search engines understand the page, and you can read your own code later.',
    usage: [
      { code: '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>Camp III</title>\n  <link rel="stylesheet" href="style.css">\n</head>\n<body>\n  …\n</body>\n</html>', note: 'The standard skeleton. Copy it to start every page.' },
      { code: '<body>\n  <header>\n    <h1>Expedition Log</h1>\n    <nav><a href="/">Home</a> <a href="/route">Route</a></nav>\n  </header>\n  <main>\n    <h2>Day 12</h2>\n    <p>Reached Camp III.</p>\n  </main>\n  <footer>Written at 7,200 m</footer>\n</body>', note: 'Landmarks. A screen reader can list "banner, navigation, main, content info" and jump to any of them.' },
      { code: '<h1>Gear guide</h1>\n  <h2>Ropes</h2>\n    <h3>Dynamic</h3>\n    <h3>Static</h3>\n  <h2>Boots</h2>', note: 'A heading outline (indented here only to show the levels).' },
    ],
    uses: ['Starting every new page from the standard skeleton.', 'Letting screen reader and keyboard users jump to the content they want.', 'Helping search engines understand what matters on the page.', 'Keeping big pages readable for you and your team.'],
    when: ['Always: every page gets the doctype, `lang`, `charset`, `viewport` and `title`.', 'Whenever a part of the page has a clear role (menu, main content, footer), use the matching landmark.'],
    whenNot: ['Don\'t use `<section>` as a generic wrapper just for styling. If it has no heading and no theme, a `<div>` is honest.', 'Don\'t put two `<main>` elements on one page.', 'Don\'t pick heading levels by size (an `<h4>` because it looks right). Pick by outline level and size it with CSS.'],
    mistakes: [
      { wrong: '(no <meta charset="utf-8"> in the head)', result: 'Fancy characters can show as junk like "â€”" or "Ã©" instead of — or é', why: 'Without it the browser may guess the wrong text encoding. Put `<meta charset="utf-8">` first in the head.' },
      { wrong: '(no viewport meta tag)', result: 'On a phone the page looks tiny and zoomed out, like a shrunken desktop site', why: 'Phone browsers assume an old desktop page about 980px wide unless the viewport tag says `width=device-width`.' },
      { wrong: '<h1>Gear</h1> … <h4>Ropes</h4>', result: '(looks fine; the outline jumps from level 1 to level 4)', why: 'Screen reader users navigating by heading think they missed two levels. Use `<h2>` and style it smaller if needed.' },
      { prose: 'Putting visible content like a `<p>` inside the `<head>`.', why: 'The browser moves it into the body for you, so it seems to work. But the head is only for page information. Keep content in the body.' },
    ],
    tips: ['Save the skeleton above as a starter file and copy it for every new page.', 'Read your headings alone, in order. If they make a sensible table of contents, the structure is good.', 'The `<title>` is what shows in bookmarks, tabs and search results. Make it specific: "Packing list · Camp III", not "Page".'],
    related: ['html', 'html-element', 'accessibility', 'responsive-design'],
  },

  // ─────────────── CSS: the clothing ───────────────
  css: {
    term: 'CSS', stands: 'Cascading Style Sheets',
    short: 'The language that sets how HTML looks: colours, sizes, spacing, layout.',
    what: 'CSS controls the appearance of a page. HTML says "this is a heading"; CSS says "headings are dark red, 32 pixels tall, with space underneath." Keeping structure (HTML) and looks (CSS) separate means you can restyle a whole site without touching its content.',
    how: 'CSS is a list of **rules**. Each rule has a **selector** (which elements) and **declarations** (what to change):\n`h1 { color: darkred; font-size: 32px; }`\n• `h1` is the selector\n• `color: darkred;` is one declaration: a **property**, a colon, a **value**, a semicolon\n\n**Three places to put CSS:**\n1. A separate file, linked in the head: `<link rel="stylesheet" href="style.css">` (best for real sites)\n2. A `<style>` element in the head (handy for one page, and what this camp uses)\n3. A `style` attribute on one element: `<p style="color: red">` (avoid; hard to maintain)\n\n**The "cascading" part:** when two rules set the same property on the same element, the browser decides who wins: the more **specific** selector wins (see CSS selectors), and if they\'re equally specific, the one **written later** wins.\n\n**Inheritance:** some properties pass down to children automatically. Set `color` or `font-family` on `body` and all the text inside gets it. Box properties like `border`, `padding` and `margin` do *not* inherit.\n\n**Units:** `px` (pixels), `%` (of the parent), `rem` (times the root font size, usually 16px), `vw`/`vh` (percent of the screen width/height). Colours can be names (`red`), hex (`#b71c1c`) or `rgb(183, 28, 28)`.\n\n**CSS fails silently.** A typo produces no error message; the browser just skips that declaration. The devtools show skipped declarations crossed out.',
    usage: [
      { code: '<style>\n  body { font-family: sans-serif; color: #222222; }\n  h1 { color: #b71c1c; font-size: 32px; }\n</style>', out: '(all text in a clean font, near-black; the h1 dark red and 32px tall)', note: 'Rules in a `<style>` element inside the head.' },
      { code: 'p { color: blue; }\np { color: green; }', out: '(paragraphs are green)', note: 'Same selector, same property: the later rule wins.' },
      { code: 'body { color: #333333; }\n/* every p, li and span inside body is now #333333 too */', note: 'Text colour inherits. `/* … */` is a CSS comment.' },
      { code: '.note { background-color: #fff3cd; padding: 8px; }', out: '(anything with class="note" gets a pale yellow background and inner space)', note: 'A class selector, the most common kind.' },
    ],
    uses: ['Every colour, font, size, gap and layout on every website.', 'Dark mode, print styles, and different layouts for phones and big screens.', 'Animations and hover effects.'],
    when: ['You want to change how something looks, not what it is.', 'The same look should apply to many elements: write one rule instead of repeating yourself.'],
    whenNot: ['For content. Text that matters belongs in the HTML, not added with CSS tricks, because screen readers and search engines may skip it.', 'For behaviour that needs logic ("when the counter hits 4, show a message"). That\'s JavaScript.', 'Avoid inline `style="…"` attributes for anything you\'ll reuse. They beat almost every other rule and become impossible to override.'],
    mistakes: [
      { wrong: 'h1 { color: red background: blue; }', result: '(neither colour applies; no error anywhere)', why: 'A missing semicolon glues the two declarations into one invalid value, so the browser throws the whole thing away. End every declaration with `;`.' },
      { wrong: 'h1 { color = red; }', result: '(ignored silently)', why: 'CSS uses a colon, not `=`: `color: red;`.' },
      { wrong: 'p { padding: 16; }', result: '(no padding at all)', why: 'Lengths need a unit: `16px`. Only `0` may go without one.' },
      { prose: 'Editing style.css but the page doesn\'t change.', why: 'Usually the `<link>` path is wrong, or the browser shows a cached old copy. Check the Network panel in the devtools, or do a hard reload, which skips the cache (the shortcut for your system is in the box below).' },
    ],
    tips: ['When a style "doesn\'t work," inspect the element in the devtools: crossed-out lines show what lost, and a warning icon marks invalid values.', 'Set your base font and colour once on `body` and let inheritance do the rest.', 'Write one declaration per line. Missing semicolons become obvious.'],
    related: ['css-selector', 'box-model', 'flexbox', 'responsive-design', 'devtools'],
    os: {
      linux: '**Hard reload** (ignore the cached copy and fetch your CSS fresh): **Ctrl+Shift+R** in Chrome and Firefox.',
      mac: '**Hard reload** (ignore the cached copy and fetch your CSS fresh): **Cmd+Shift+R** in Chrome and Firefox. In Safari, **Cmd+Shift+R** opens Reader view instead; use **Cmd+Option+E** (empty caches) and then **Cmd+R**, or hold **Option** while clicking Reload.',
      windows: '**Hard reload** (ignore the cached copy and fetch your CSS fresh): **Ctrl+Shift+R** or **Ctrl+F5** in Chrome, Edge and Firefox.',
      chromeos: '**Hard reload** (ignore the cached copy and fetch your CSS fresh): **Ctrl+Shift+R** in Chrome.',
      phone: 'Phone browsers have no hard-reload shortcut. Closing the tab and reopening the page usually fetches fresh files; in this game, the Preview button always reloads everything.',
    },
  },
  'css-selector': {
    term: 'CSS selector', short: 'The part of a CSS rule that picks which elements it styles.',
    what: 'A **selector** is a pattern that matches elements on the page. `h1` matches every h1; `.note` matches everything with class "note"; `#count` matches the one element with id "count". The same selector language is used by JavaScript\'s `querySelector`, so learning it once pays twice.',
    how: '**The core selectors:**\n• `p`: **type** selector, every `<p>`\n• `.item`: **class** selector (dot), everything with `class="item"`\n• `#count`: **id** selector (hash), the element with `id="count"`\n• `*`: everything\n\n**Combining them:**\n• `nav a`: a **descendant**: any `<a>` anywhere inside a `<nav>` (the space means "inside")\n• `ul > li`: a **child**: `<li>` directly inside a `<ul>`\n• `.item.packed`: **both** classes on the same element (no space!)\n• `h1, h2`: a **group**: same rule for h1 and h2\n• `input[type="email"]`: an **attribute** selector\n\n**Pseudo-classes** match a state, written with a colon:\n• `a:hover`: while the pointer is over it\n• `button:focus-visible`: while focused from the keyboard\n• `li:first-child`, `li:last-child`, `li:nth-child(2)`\n• `:not(.packed)`: everything except\n\n**Specificity (who wins):** when rules clash, the more specific selector wins, whatever the order. Roughly: an **id** beats any number of **classes**, and a **class** beats any number of **type** selectors. Inline `style` attributes beat all of them. Only when specificity ties does "later wins" decide. (`!important` jumps the queue; avoid it, it starts an arms race.)',
    usage: [
      { code: '.packed { text-decoration: line-through; }', out: '(every element with class "packed" gets crossed out)', note: 'Class selector: the workhorse.' },
      { code: 'nav a { color: white; }', note: 'Only links inside the nav turn white; other links keep their colour.' },
      { code: '#count { font-weight: bold; }\np { font-weight: normal; }', out: '(<p id="count"> stays bold)', note: 'The id is more specific than the type selector, so it wins even though it comes first.' },
      { code: 'button:focus-visible { outline: 3px solid #1565c0; }', note: 'A clear focus ring for keyboard users.' },
      { code: '.item.packed { opacity: 0.6; }\n.item .packed { opacity: 0.6; }', note: 'Line 1: one element with both classes. Line 2 (with a space): a .packed element *inside* an .item. Very different.' },
    ],
    uses: ['Styling groups of elements with classes (`.card`, `.button`, `.error`).', 'Styling states: hover, focus, checked, disabled.', 'Finding elements from JavaScript: `document.querySelector(\'.item.packed\')`.'],
    when: ['Use **classes** for almost all styling: reusable, low specificity, easy to override.', 'Use descendant selectors to style things in context (`.card h2`).'],
    whenNot: ['Avoid styling with `#ids`. Their high specificity makes later changes painful. Keep ids for JavaScript and labels.', 'Avoid long chains like `body main section ul li a span`. They break the moment the HTML changes.', 'Don\'t reach for `!important` to win a fight. Find out why you\'re losing (the devtools tell you) and fix the selector.'],
    mistakes: [
      { wrong: 'item { color: green; }', result: '(nothing changes)', why: 'Without a dot, `item` looks for an `<item>` element, which doesn\'t exist. Classes need the dot: `.item`.' },
      { wrong: '.btn .primary { … }  (meant one element with both classes)', result: '(matches nothing)', why: 'The space means "inside." For one element with both classes, write `.btn.primary`.' },
      { wrong: '<p class=".note">', result: '(the .note rule doesn\'t apply)', why: 'The dot belongs only in the CSS selector. In the HTML, write `class="note"`.' },
      { prose: 'Adding a rule that seems to be ignored.', why: 'Usually a more specific rule is winning. Inspect the element: your declaration will be crossed out, and the winner listed above it.' },
    ],
    tips: ['Read selectors right to left: `nav a` = "links… that are inside a nav."', 'Test a selector instantly in the devtools Console: `document.querySelectorAll(\'.item\')` shows exactly what it matches.', 'A shared vocabulary of class names (`.card`, `.item`, `.packed`) makes both CSS and JavaScript easier.'],
    related: ['css', 'html-attribute', 'query-selector', 'box-model'],
  },
  'box-model': {
    term: 'Box model', short: 'Every element is a box: content, then padding, then border, then margin.',
    what: 'To the browser, **every element is a rectangle**. The box model describes its four layers, from the inside out: the **content** (text or image), **padding** (space inside the border), the **border** (a line around it) and **margin** (space outside, pushing other boxes away).',
    how: 'Picture a framed photo: the photo is the **content**, the mat around it is the **padding**, the frame is the **border**, and the gap to the next frame on the wall is the **margin**.\n\n• `padding: 16px` adds space inside. The background colour fills it.\n• `border: 2px solid #2e7d32` draws a line: width, **style** and colour. Without a style (`solid`, `dashed`, `dotted`) there\'s no border at all.\n• `margin: 24px` adds space outside. It\'s always transparent.\n• One value means all four sides; you can also set sides separately: `padding-top`, `margin-left`, and so on. `padding: 8px 16px` means 8px top and bottom, 16px left and right.\n\n**The width trap:** by default, `width` sets the **content only**. Padding and border are added on top:\n`width: 200px; padding: 20px; border: 2px solid` → 200 + 20 + 20 + 2 + 2 = **244px** on screen.\n\nThe fix almost every site uses: `box-sizing: border-box`, which makes `width` include padding and border, so 200px means 200px.\n\n**Margin collapse:** when two block boxes are stacked, their vertical margins don\'t add up; the bigger one wins. 20px below one paragraph and 30px above the next gives a 30px gap, not 50px.\n\n**Inline elements** (`<span>`, `<a>`) ignore `width`, `height` and top/bottom margins. Make them `display: inline-block` or `block` if you need those.',
    usage: [
      { code: '.card {\n  width: 200px;\n  padding: 20px;\n  border: 2px solid black;\n}', out: '(the card is 244px wide on screen)', note: 'Default content-box: padding and border are added outside the 200px.' },
      { code: '.card {\n  box-sizing: border-box;\n  width: 200px;\n  padding: 20px;\n  border: 2px solid black;\n}', out: '(the card is exactly 200px wide; the content area shrinks to 156px)', note: 'border-box: the width includes padding and border.' },
      { code: '*, *::before, *::after { box-sizing: border-box; }', note: 'The usual first line of a stylesheet: border-box for everything.' },
      { code: 'button { padding: 12px 20px; }', note: 'Bigger padding = a bigger tap target, which phone users (and anyone with shaky hands) need.' },
    ],
    uses: ['Spacing things out so a page can breathe.', 'Cards, buttons and panels: padding inside, a border, margin between them.', 'Debugging "why is this too wide / why is there a gap here?", which is nearly always the box model.'],
    when: ['Use **padding** for space *inside* a box (between its border and its content), especially to make buttons easier to tap.', 'Use **margin** for space *between* boxes.', 'Use `box-sizing: border-box` on every project, so widths mean what they say.'],
    whenNot: ['Don\'t use empty `<p>` or `<br>` tags to make space. That\'s margin\'s job.', 'Don\'t give boxes fixed pixel widths that might be wider than a phone screen; use `max-width` instead (see Responsive design).', 'Don\'t use padding when you want the background colour to stop at the edge; padding is filled by the background, margin isn\'t.'],
    mistakes: [
      { wrong: '.card { border-width: 2px; }', result: '(no border appears; its computed width is 0px)', why: 'A border needs a style. Without `border-style: solid` (or the shorthand `border: 2px solid black`), the style defaults to none and the border disappears.' },
      { wrong: '.panel { width: 100%; padding: 16px; }', result: '(the panel sticks out 32px; the phone page scrolls sideways)', why: '100% of the parent PLUS 32px of padding is too wide. Add `box-sizing: border-box`.' },
      { prose: 'Setting `margin-top` on a `<span>` and nothing moves.', why: 'Inline elements ignore vertical margins and widths. Use `display: inline-block` or `block`.' },
      { prose: 'Two paragraphs with `margin: 20px` each, expecting a 40px gap.', why: 'Vertical margins collapse: the gap is 20px. If you need more, make one margin bigger.' },
    ],
    tips: ['The devtools show a coloured box-model diagram for any element (in Chrome: Elements → Computed). Hover each layer to see it highlighted on the page.', 'Tap targets should be at least about 44×44 pixels. Padding is the easy way there.', 'Add `outline: 1px solid red` to a box temporarily to see exactly where it is; outlines don\'t change layout like borders do.'],
    related: ['css', 'flexbox', 'responsive-design', 'devtools'],
  },
  flexbox: {
    term: 'Flexbox', short: 'A CSS layout tool that lines children up in a row or column and spaces them out.',
    what: '**Flexbox** (the flexible box layout) arranges the children of an element along a line: side by side in a **row** or stacked in a **column**. It handles spacing, alignment and wrapping, which used to take painful hacks.',
    how: 'You switch it on with `display: flex` on the **parent** (the flex container). Its direct children become **flex items** and line up in a row.\n\nThe direction the items line up in is the **main axis**.\n\n**On the container:**\n• `flex-direction: row` (default, left to right) or `column` (top to bottom). This sets the **main axis**.\n• `justify-content`: spacing along the **main axis**. `flex-start` (default), `center`, `flex-end`, `space-between` (first and last at the edges, equal gaps between), `space-around`, `space-evenly`.\n• `align-items`: alignment on the **cross axis** (the other direction). `stretch` (default), `center`, `flex-start`, `flex-end`.\n• `gap: 12px`: space between items, and none at the edges.\n• `flex-wrap: wrap`: let items flow onto a new line when they run out of room. The default `nowrap` squeezes them onto one line.\n\n**On an item:**\n• `flex: 1`: grow to share leftover space (two items with `flex: 1` split it evenly)\n• `align-self`: override `align-items` for just this item\n\nRemember the swap: in a `column`, `justify-content` works **vertically** and `align-items` works **horizontally**, because the axes turn with the direction.',
    usage: [
      { code: '.gear {\n  display: flex;\n  gap: 8px;\n}', out: '[Rope] [Axe] [Tent]   (side by side, 8px apart)', note: 'The children line up in a row.' },
      { code: '.top-bar {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}', out: '[Logo]                       [Menu]', note: 'Logo at the left edge, menu at the right, both centred vertically.' },
      { code: '.stack {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}', note: 'A vertical stack with even spacing, handy for forms on phones.' },
      { code: '.chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}', note: 'Tags or buttons that wrap onto new lines on narrow screens instead of overflowing.' },
      { code: '.search { display: flex; }\n.search input { flex: 1; }', note: 'The input grows to fill the row; the button next to it keeps its size.' },
    ],
    uses: ['Navigation bars: logo left, links right.', 'Rows of buttons, cards or tags.', 'Centring something (`justify-content: center; align-items: center;`).', 'Form rows where an input stretches and its button doesn\'t.'],
    when: ['You\'re laying things out in **one direction**: a row or a column.', 'You need equal spacing or alignment without fiddly margins.'],
    whenNot: ['For full two-dimensional grids (rows AND columns that must line up, like a photo gallery or calendar), CSS Grid (`display: grid`) is the better tool.', 'For plain text flowing in paragraphs. Normal flow already does that.', 'Don\'t put `display: flex` on everything "just in case." It changes how children size themselves and can surprise you.'],
    mistakes: [
      { wrong: '.gear li { display: flex; }  (wanted the items in a row)', result: '(still stacked vertically)', why: 'Flex goes on the **parent**: `.gear { display: flex; }`. Its children are what get laid out.' },
      { wrong: '.box { display: flex; align-items: center; }  (expecting vertical centring on the page)', result: '(nothing seems to move)', why: 'The container is only as tall as its content, so there\'s no room to centre in. Give it a height, e.g. `min-height: 100vh`.' },
      { wrong: '.list { display: flex; flex-direction: column; justify-content: center; }  (wanted horizontal centring)', result: '(items centre vertically, or not at all)', why: 'In a column the axes swap: use `align-items: center` to centre horizontally.' },
      { prose: 'Ten cards in a flex row on a phone, all squeezed thin.', why: 'The default is `nowrap`. Add `flex-wrap: wrap` so they flow onto new lines.' },
    ],
    tips: ['Prefer `gap` over margins between flex items: no extra space at the edges, no maths.', 'Chrome and Firefox devtools show a "flex" badge next to flex containers in the Elements panel. Click it to see the axes and gaps drawn on the page.', 'Main axis = `justify-content`, cross axis = `align-items`. Say "justify along, align across."'],
    related: ['css', 'box-model', 'responsive-design', 'css-selector'],
  },
  'responsive-design': {
    term: 'Responsive design', short: 'Building one page that adapts to any screen, from a phone to a wide monitor.',
    what: 'A **responsive** page rearranges itself to fit whatever screen it\'s on. The same HTML and CSS look right on a 360px-wide phone and a 1920px-wide monitor. Since most people browse on phones, responsive isn\'t optional; it\'s the default expectation.',
    how: '**Four tools do almost all of it:**\n\n1. **The viewport meta tag** in the head: `<meta name="viewport" content="width=device-width, initial-scale=1">`. Without it, phones pretend to be a ~980px desktop and shrink the whole page.\n\n2. **Flexible sizes** instead of fixed ones: `%`, `rem`, `vw`, and `max-width`. `max-width: 600px; width: 100%;` means "fill the screen, but never wider than 600px."\n\n3. **Flexible images**: `img { max-width: 100%; height: auto; }` so pictures shrink to fit instead of overflowing.\n\n4. **Media queries**: CSS that only applies when a condition is true:\n`@media (min-width: 700px) { .gear { flex-direction: row; } }`\n"When the screen is at least 700px wide, put the gear in a row."\n\n**Mobile-first:** write the phone layout as your normal CSS, then add `min-width` media queries to enhance it for bigger screens. Small screens get the simplest CSS, and you\'re forced to decide what really matters.\n\n**Breakpoints** are the widths where your layout changes. Pick them where *your content* starts to look wrong, not from a list of device sizes.',
    usage: [
      { code: '<meta name="viewport" content="width=device-width, initial-scale=1">', note: 'Line one of responsive design. Goes in the head of every page.' },
      { code: '.page {\n  max-width: 700px;\n  margin: 0 auto;\n  padding: 16px;\n}', note: 'Full width on phones, a comfortable 700px column on big screens, centred by the auto side margins.' },
      { code: '.gear { display: flex; flex-direction: column; gap: 8px; }\n\n@media (min-width: 700px) {\n  .gear { flex-direction: row; }\n}', out: 'Phone: items stacked.  700px and wider: items in a row.', note: 'Mobile-first: the column is the default; the media query upgrades it.' },
      { code: 'img { max-width: 100%; height: auto; }', note: 'Images never burst out of their container.' },
    ],
    uses: ['Every modern site and web app: one codebase for phone, tablet and desktop.', 'Turning a sidebar into a stacked section on phones.', 'Making tap targets and text comfortable on small screens.'],
    when: ['Always. Assume your page will be opened on a phone first.', 'Use a media query when the layout genuinely needs to change, not for every small tweak.'],
    whenNot: ['Don\'t set fixed widths like `width: 1200px` on page containers. That guarantees sideways scrolling on phones.', 'Don\'t disable zoom (`maximum-scale=1` or `user-scalable=no`). People with low vision rely on pinch-zoom.', 'Don\'t hide important content on phones with `display: none` just to save space. Phone users need it too.'],
    mistakes: [
      { wrong: '.wrapper { width: 1200px; }', result: '(on a phone the page scrolls sideways and everything is cut off)', why: 'Use `max-width: 1200px; width: 100%;` so it can shrink.' },
      { wrong: '@media (min-width: 700) { … }', result: '(the whole block is ignored, silently)', why: 'The width needs a unit: `700px`. CSS skips anything it can\'t read.' },
      { prose: 'Testing only on your laptop\'s full-width browser.', why: 'The page may be broken on phones and you\'d never know. Use the devtools device mode, and check on a real phone too.' },
      { prose: 'A big image making a phone page scroll sideways.', why: 'Images default to their natural size. Add `img { max-width: 100%; height: auto; }`.' },
    ],
    tips: ['Build and check at 360px wide first; if it works there, widening is easy.', 'Sideways scrolling on a phone almost always means one element is too wide. In the devtools, look for the box that sticks out.', 'Use `rem` for font sizes so text respects the reader\'s browser font-size setting.'],
    related: ['flexbox', 'box-model', 'page-structure', 'devtools'],
    os: {
      linux: '**Test phone sizes in the devtools:** open them (F12), then press **Ctrl+Shift+M**. Chrome calls it the Device Toolbar; Firefox calls it Responsive Design Mode. Pick a phone size from the menu at the top.',
      mac: '**Test phone sizes in the devtools:** in Chrome, open them (Cmd+Option+I) and press **Cmd+Shift+M**. In Firefox press **Cmd+Option+M**. In Safari, use Develop → Enter Responsive Design Mode (**Ctrl+Cmd+R**).',
      windows: '**Test phone sizes in the devtools:** open them (F12), then press **Ctrl+Shift+M** in Chrome, Edge or Firefox.',
      chromeos: 'Open the devtools with **Ctrl+Shift+I**, then press **Ctrl+Shift+M** for the Device Toolbar.',
      phone: 'You\'re already on the real thing. Open your page on the phone itself, rotate it to landscape, and try pinch-zooming. That\'s the best test there is.',
    },
  },

  // ─────────────── JavaScript in the browser: the muscles ───────────────
  dom: {
    term: 'The DOM', stands: 'Document Object Model',
    short: 'The live tree of objects the browser builds from your HTML, which JavaScript can read and change.',
    what: 'When the browser reads your HTML, it doesn\'t keep it as text. It builds a **tree of objects**, one object per element, called the **DOM**. What you see on screen is drawn from that tree. JavaScript can change the tree (edit text, add items, switch classes) and the screen updates instantly.',
    how: 'Picture the HTML as a family tree: `<html>` at the top, `<head>` and `<body>` as its children, and so on down. Every element becomes a **node** you can grab from JavaScript.\n\nThe whole tree is available as the global object `document`. (It only exists in the browser. In Node, `document` is not defined.)\n\n**Changing things, once you\'ve grabbed an element `el`:**\n• `el.textContent = "Packed!"`: replace its text (safe: treated as plain text)\n• `el.classList.add("packed")` / `.remove(…)` / `.toggle(…)`: switch classes, so CSS does the styling\n• `el.setAttribute("aria-pressed", "true")`: set an attribute\n• `el.style.color = "red"`: set one inline style (prefer classes)\n• `document.createElement("li")` makes a new element; `list.append(li)` puts it on the page; `el.remove()` takes one off\n\n**View source vs the DOM:** view-source shows the original HTML file. The devtools **Elements** panel shows the **live DOM**, including everything JavaScript has changed since. When they disagree, the Elements panel is the truth.\n\n**Timing matters:** the browser builds the tree top to bottom. A `<script>` runs the moment the browser reaches it, so a script in the `<head>` runs before the body exists. Put scripts at the **end of the body**, or add `defer`: `<script src="app.js" defer></script>`.',
    usage: [
      { code: 'const status = document.querySelector("#status")\nstatus.textContent = "Camp III reached"', out: '(the paragraph with id="status" now reads "Camp III reached")', note: 'Grab an element, change its text. The screen updates.' },
      { code: 'const li = document.createElement("li")\nli.textContent = "Headlamp"\ndocument.querySelector("#gear").append(li)', out: '(a new "Headlamp" item appears at the end of the list)', note: 'Make, fill, attach: the three steps for adding anything.' },
      { code: 'const rope = document.querySelector("#rope")\nrope.classList.toggle("packed")', note: 'Adds "packed" if it\'s missing, removes it if it\'s there. Pair it with a `.packed` CSS rule.' },
      { code: 'document.querySelector("#gear").innerHTML = "<li>Rope</li><li>Axe</li>"', note: '`innerHTML` treats the string as HTML and replaces everything inside. Fine for your own fixed text; dangerous with anything a user typed (see whenNot).' },
    ],
    uses: ['Every interactive page: checklists, counters, menus that open, live search results, form messages.', 'Showing data fetched from an API: create elements from the JSON and append them.', 'Frameworks like React (Camp J) do exactly this for you behind the scenes.'],
    when: ['Something on the page should change after it loads, because the user did something or data arrived.', 'Use `textContent` for text and `classList` for appearance, almost always.'],
    whenNot: ['Never put user-typed text into `innerHTML`. If someone types `<img src=x onerror="…">`, the browser runs it as code. That attack is called **cross-site scripting (XSS)**. Use `textContent`, which shows it as harmless text.', 'Don\'t use JavaScript to build content that could just be written in the HTML. It\'s slower, and the page is empty if the script fails.', 'Avoid setting lots of `el.style` properties; add a class and let CSS do it.'],
    mistakes: [
      { wrong: '<head><script>document.querySelector("#status").textContent = "Hi"</script></head>', result: 'TypeError: Cannot set properties of null (setting \'textContent\')', why: 'The script ran before the browser had built the body, so `querySelector` found nothing and returned `null`. Move the script to the end of the body, or use `defer`.' },
      { wrong: 'document.querySelector("#status").textContent("Hi")', result: 'TypeError: document.querySelector(...).textContent is not a function', why: '`textContent` is a property, not a function. Assign to it: `.textContent = "Hi"`.' },
      { prose: 'Editing the page in the devtools Elements panel, then reloading, and all your changes are gone.', why: 'The devtools change the live DOM in memory, not your file. Copy what works back into your code.' },
      { wrong: 'node app.js  (a file that uses document)', result: 'ReferenceError: document is not defined', why: '`document` only exists in a browser. Node has no page.' },
    ],
    tips: ['In the devtools Console, `$0` is whatever element you last selected in the Elements panel. Try `$0.textContent = "hi"`.', 'When a change "doesn\'t show," `console.log` the element first. If it prints `null`, your selector or your timing is wrong.', 'Let CSS own the looks: JavaScript just adds and removes classes.'],
    related: ['query-selector', 'events', 'html', 'devtools'],
  },
  'query-selector': {
    term: 'querySelector / querySelectorAll', short: 'Find elements on the page from JavaScript, using CSS selectors.',
    what: '`document.querySelector(selector)` returns the **first** element that matches a CSS selector, or `null` if none does. `document.querySelectorAll(selector)` returns **all** matches as a list (a NodeList), which is empty if none match.',
    how: 'They take exactly the same selectors as CSS: `"#count"`, `".item"`, `"nav a"`, `".item.packed"`, `"input[type=email]"`. That\'s why learning CSS selectors pays twice.\n\n• `querySelector("#count")`: one element (or `null`)\n• `querySelectorAll(".item")`: a NodeList of every match\n\nA NodeList is **like** an array but not quite one:\n• it has `.length` and `.forEach(…)`, and works in a `for…of` loop\n• it does **not** have `.map` or `.filter`. Convert it first: `Array.from(list)` or `[...list]`\n• it\'s a **snapshot**: elements added later don\'t appear in it. Query again to see them.\n\nYou can search inside one element instead of the whole page: `card.querySelector("h2")` finds the first h2 inside that card.\n\nThe older `document.getElementById("count")` does the same job as `querySelector("#count")` (note: no `#` there). You\'ll see both.',
    usage: [
      { code: 'const count = document.querySelector("#count")\nconsole.log(count.textContent)', out: 'Packed: 0 of 4', note: 'One element, by id.' },
      { code: 'const items = document.querySelectorAll(".item")\nconsole.log(items.length)', out: '4', note: 'Every element with class "item".' },
      { code: 'document.querySelectorAll(".item").forEach(item => {\n  item.classList.add("checked")\n})', note: 'Do the same thing to every match.' },
      { code: 'const packed = document.querySelectorAll(".item.packed").length', note: 'Counting matches: how many items are packed right now.' },
      { code: 'console.log(document.querySelector(".missing"))', out: 'null', note: 'No match gives `null`, not an error. The error comes later, when you use it.' },
    ],
    uses: ['The first line of almost every browser script: grab the elements you need.', 'Counting things on the page (how many items are checked).', 'Applying a change to a whole group (mark every item packed).'],
    when: ['Use `querySelector` when you want one specific element (usually by id).', 'Use `querySelectorAll` when you want every element of a kind.'],
    whenNot: ['Don\'t call `querySelectorAll` once at the start and expect it to include items you add later; it\'s a snapshot. Query again when you need fresh results.', 'Don\'t query the same element inside a loop that runs thousands of times. Grab it once into a `const` and reuse it.', 'Don\'t rely on a selector that only works because of the page\'s current order (`li:nth-child(3)`) when an id or class would be clearer.'],
    mistakes: [
      { wrong: 'document.querySelector("status").textContent = "Hi"', result: 'TypeError: Cannot set properties of null (setting \'textContent\')', why: 'Without `#`, it looks for a `<status>` element. Write `"#status"` for an id or `".status"` for a class.' },
      { wrong: 'document.querySelectorAll(".item").textContent = "Packed"', result: '(nothing changes, and no error)', why: 'A NodeList is a list, not an element. Setting `.textContent` on it just sticks a useless property on the list. Loop with `.forEach` and set each item.' },
      { wrong: 'document.querySelectorAll(".item").map(i => i.textContent)', result: 'TypeError: document.querySelectorAll(...).map is not a function', why: 'NodeLists have `forEach` but not `map`. Use `[...document.querySelectorAll(".item")].map(…)`.' },
      { wrong: 'document.getElementById("#count")', result: 'null', why: '`getElementById` takes the bare id, no `#`. Either `getElementById("count")` or `querySelector("#count")`.' },
    ],
    tips: ['Store elements you use more than once in a `const` at the top of your script.', 'Test selectors live in the devtools Console before putting them in code.', 'If you get `null`, check three things: the `#` or `.`, the spelling, and whether the script runs after the element exists.'],
    related: ['dom', 'css-selector', 'events'],
  },
  events: {
    term: 'Events (addEventListener)', short: 'Run a function when something happens on the page: a click, a key press, a form submit.',
    what: 'An **event** is the browser announcing that something happened: a click, a tap, a key press, typing in a box, a form being sent. `element.addEventListener("click", handler)` says "when this element is clicked, run my `handler` function." Events are how a page reacts to people.',
    how: 'A listener does nothing until its event happens. Then the browser runs your function.\n\n`button.addEventListener("click", () => { … })`\n• the first argument is the **event name**, a string\n• the second is the **function to run**: the *listener* or *handler*. You pass the function itself; the browser calls it later, every time the event happens.\n\n**The event object:** the browser passes your function one argument with details, usually called `event` or `e`:\n• `e.target`: the element the event happened on\n• `e.key`: which key was pressed (keyboard events)\n• `e.preventDefault()`: cancel the browser\'s default action (like a form reloading the page)\n\n**Events you\'ll use most:**\n• `click`: a click, a tap, OR Enter/Space on a focused button\n• `input`: every change while typing in a text box\n• `change`: a checkbox ticked, a dropdown picked, or a text box left after editing\n• `submit`: a form being sent (listen on the `<form>`, not the button)\n• `keydown`: a key pressed\n\n**Keyboard users for free:** a real `<button>` fires `click` when it\'s focused and someone presses Enter or Space. A `<div>` with a click listener does not, and it can\'t even be reached with Tab. Use buttons for things you click.\n\n**Event delegation:** clicks *bubble up* through the parents. One listener on a list can handle clicks on every item, including ones added later, by checking `e.target`.',
    usage: [
      { code: 'const btn = document.querySelector("#call")\nbtn.addEventListener("click", () => {\n  document.querySelector("#log").textContent = "Base Camp, come in."\n})', out: '(tapping the button changes the log text)', note: 'The classic pattern: find, listen, change the DOM.' },
      { code: 'let packed = 0\nbtn.addEventListener("click", () => {\n  packed++\n  count.textContent = `Packed: ${packed}`\n})', out: 'Packed: 1, then Packed: 2, … on each tap', note: 'The variable lives outside the handler, so it remembers between clicks.' },
      { code: 'search.addEventListener("input", e => {\n  console.log(e.target.value)\n})', out: 'r\nro\nrop\nrope', note: 'Fires on every keystroke in the box.' },
      { code: 'document.querySelector("#gear").addEventListener("click", e => {\n  if (e.target.matches(".item")) e.target.classList.toggle("packed")\n})', note: 'Delegation: one listener on the list handles every item, even new ones.' },
    ],
    uses: ['Buttons that do things, menus that open, tabs that switch.', 'Live search and character counters (the `input` event).', 'Form handling (the `submit` event).', 'Keyboard shortcuts (the `keydown` event).'],
    when: ['The page should react to something the user does.', 'Use `click` on buttons and links, `submit` on forms, `input` for live typing feedback.'],
    whenNot: ['Don\'t put click listeners on `<div>`s or `<span>`s to make fake buttons. Keyboard and screen reader users can\'t use them. Use `<button>`.', 'Don\'t add the same listener inside a loop or another handler by accident: every extra copy runs too, so one click fires twice, three times…', 'Don\'t use the old `onclick="…"` attribute in new code. It mixes JavaScript into HTML and only allows one handler.'],
    mistakes: [
      { wrong: 'btn.addEventListener("click", pack())', result: '(pack runs once immediately when the page loads, then clicks do nothing)', why: 'The brackets *call* the function right now and pass its return value (`undefined`). Pass the function itself: `addEventListener("click", pack)`.' },
      { wrong: 'btn.addEventListener("onclick", pack)', result: '(nothing ever happens; no error)', why: 'The event is called `"click"`. `"onclick"` is the attribute name. A misspelled event name is silently accepted and never fires.' },
      { wrong: 'btn.addEventListener("click", () => { … })  (btn is null)', result: 'TypeError: Cannot read properties of null (reading \'addEventListener\')', why: 'Your querySelector found nothing. Check the selector, and that the script runs after the button exists.' },
      { prose: 'Clicking a button inside a `<form>` and the page flashes and resets.', why: 'Buttons inside forms submit the form by default, which reloads the page. Listen for `submit` and call `e.preventDefault()`, or give non-submit buttons `type="button"`.' },
    ],
    tips: ['Name handler functions for what they do (`togglePacked`, `addItem`). It makes `addEventListener("click", addItem)` read like a sentence.', 'Put a `console.log("clicked")` as the first line of a handler when debugging. If it never prints, the listener isn\'t attached.', 'Test every interactive thing with the keyboard alone: Tab to it, press Enter or Space.'],
    related: ['dom', 'query-selector', 'forms', 'accessibility'],
  },
  forms: {
    term: 'Forms (form, label, input)', short: 'The HTML for collecting what people type, tick or choose, and the JavaScript to read it.',
    what: 'A **form** is how a page collects information: a sign-up, a search box, a "add item" field. It\'s built from a `<form>` element containing **inputs** (boxes, checkboxes, dropdowns), a **label** for each one, and a **submit button**.',
    how: '**The pieces:**\n• `<form>`: wraps the fields; fires a `submit` event when sent\n• `<label for="email">Email</label>`: the visible name of a field. Its `for` must match the input\'s `id`. Tapping the label focuses the input, and screen readers read it out.\n• `<input id="email" type="email" name="email">`: the field itself (a void element)\n• `<button type="submit">Join</button>`: sends the form. Inside a form, a `<button>` with no type **is** a submit button.\n\n**Input types** change the keyboard and the built-in checks: `text`, `email`, `password`, `number`, `search`, `checkbox`, `radio`, `date`. On phones, `type="email"` shows an @ key and `type="number"` a number pad.\n\n**Useful attributes:** `required` (can\'t be empty), `placeholder` (a faded hint, NOT a label), `value` (the starting value), `name` (the key the data is sent under), `min`/`max`, `maxlength`.\n\n**Handling it in JavaScript:**\n```\nform.addEventListener("submit", e => {\n  e.preventDefault()           // stop the page reloading\n  const name = input.value     // read what was typed\n})\n```\nBy default, submitting a form sends the data to a server and **loads a new page**. `e.preventDefault()` stops that so your JavaScript can handle it.\n\n**`.value` is always a string**, even for `type="number"`: `"5" + 1` is `"51"`. Convert with `Number(input.value)`.\n\n**Built-in validation:** with `required` or `type="email"`, the browser blocks the submit and shows a message if the field is wrong, before your submit handler even runs. Helpful, but anyone can bypass it, so a server must always check again (Camps 9 and 10).',
    usage: [
      { code: '<form id="signup">\n  <label for="name">Climber name</label>\n  <input id="name" name="name" required>\n  <button type="submit">Join the team</button>\n</form>', out: 'Climber name [__________] [Join the team]', note: 'A complete, accessible form. Tapping "Climber name" focuses the box.' },
      { code: 'const form = document.querySelector("#signup")\nform.addEventListener("submit", e => {\n  e.preventDefault()\n  const name = document.querySelector("#name").value\n  document.querySelector("#welcome").textContent = `Welcome, ${name}!`\n})', out: 'Welcome, Climber!', note: 'Read the value INSIDE the handler, at the moment of submitting.' },
      { code: '<label><input type="checkbox" id="oxygen"> Bottled oxygen</label>', note: 'Wrapping the input inside its label also connects them, no `for` needed.' },
      { code: 'const kg = Number(document.querySelector("#weight").value)\nconsole.log(kg + 1)', out: '13   (if the box held "12")', note: 'Convert before doing maths, or you get "121".' },
    ],
    uses: ['Sign-up and log-in pages, search boxes, comment boxes, checkout pages.', 'Adding items in apps (to-do lists, packing lists).', 'Settings pages: checkboxes and dropdowns.'],
    when: ['You need input from the user. Use a real `<form>` so Enter submits it, the browser can validate it, and assistive tech understands it.', 'Give every input a visible `<label>`.'],
    whenNot: ['Don\'t use `placeholder` as the only label. It vanishes as soon as someone types, is often too faint to read, and isn\'t reliably announced.', 'Don\'t trust browser validation for anything that matters. It can be switched off in a second; the server must check too.', 'Don\'t ask for data you don\'t need. Every extra field is a privacy risk and a reason to give up.'],
    mistakes: [
      { prose: 'Your submit handler updates the page, it flashes, and everything resets.', why: 'The form submitted for real and the page reloaded. Call `e.preventDefault()` first thing in the submit handler.' },
      { wrong: 'const name = input.value  (at the top of the script)\nform.addEventListener("submit", e => { … name … })', result: '(name is always "" or the starting value)', why: 'That line ran once when the page loaded, before anyone typed. Read `.value` inside the handler.' },
      { wrong: '<label>Email</label> <input id="email">', result: '(the label isn\'t connected; tapping it does nothing; screen readers say "edit text" with no name)', why: 'Add `for="email"` to the label so it points at the input\'s id.' },
      { wrong: 'form.addEventListener("click", …)  (wanted the submit)', result: '(fires on every click anywhere in the form, and Enter-to-submit is missed)', why: 'Listen for `"submit"` on the form. It catches the button AND pressing Enter in a field.' },
    ],
    tips: ['Use the right `type`: phone users get the right keyboard for free.', 'Put helpful text (like "8+ characters") in visible text near the field, not only in the placeholder.', 'After handling a submit, `form.reset()` clears all the fields.'],
    related: ['events', 'accessibility', 'html-attribute', 'dom'],
  },

  // ─────────────── For everyone ───────────────
  accessibility: {
    term: 'Accessibility (a11y)', short: 'Building pages everyone can use, including people who can\'t see, hear, use a mouse, or read small low-contrast text.',
    what: '**Accessibility** means people with disabilities can use what you build: blind people using **screen readers** (software that reads the page aloud), people who use only a **keyboard**, people with **low vision** or **colour blindness**, people with tremors who can\'t hit tiny buttons. It\'s often written **a11y**: a, 11 letters, y.\n\nIt also helps everyone else: a broken arm, bright sunlight on a phone, a noisy room, an old laptop. And in many countries it\'s a legal requirement for public and business sites.',
    how: 'The internationally used guidelines are the **WCAG** (Web Content Accessibility Guidelines). Most of the value comes from a handful of habits:\n\n**1. Semantic HTML first.** Real `<button>`, `<a href>`, `<h1>`–`<h6>`, `<nav>`, `<main>`, `<label>`. They come with keyboard support and screen reader announcements built in. Most accessibility bugs are `<div>`s pretending to be something else.\n\n**2. Text alternatives for images.** Every `<img>` needs `alt`:\n• describe what matters in context: `alt="Climbers clipped to a fixed rope on a steep ice wall"`\n• don\'t start with "image of"; screen readers already say "image"\n• purely decorative images get an **empty** alt, `alt=""`, so they\'re skipped\n• with no alt at all, screen readers often read the **file name** ("IMG underscore 2041 dot jpg")\n\n**3. Every input has a label.** `<label for="…">` connected to the input\'s id.\n\n**4. Keyboard works everywhere.** Press **Tab** to move between links, buttons and inputs, **Enter**/**Space** to activate. There must be a visible **focus outline** showing where you are. Never remove it (`outline: none`) without adding a replacement.\n\n**5. Colour contrast.** Text must stand out from its background. WCAG level AA asks for a contrast ratio of at least **4.5:1** for normal text and **3:1** for large text (about 24px, or about 19px bold). Light grey `#999999` on white is only about 2.8:1: it fails. `#767676` on white is about 4.5:1, the lightest grey that passes.\n\n**6. Don\'t rely on colour alone.** "Required fields are red" fails colour-blind users. Add text or an icon too.\n\n**7. Set the language:** `<html lang="en">` so screen readers use the right pronunciation.\n\n**ARIA** attributes (like `aria-label`, `aria-pressed="true"`) add extra information for assistive tech. The first rule of ARIA: **if a native HTML element does the job, use it instead**. ARIA changes what\'s announced, but adds no behaviour.',
    usage: [
      { code: '<img src="ridge.jpg" alt="A line of climbers on a knife-edge snow ridge">', note: 'Meaningful image: describe what it shows and why it\'s there.' },
      { code: '<img src="divider.png" alt="">', note: 'Decorative: empty alt, so screen readers skip it.' },
      { code: '<div class="btn" onclick="pack()">Pack</div>\n<button type="button" onclick="pack()">Pack</button>', note: 'Line 1 can\'t be reached with Tab and ignores Enter. Line 2 gets focus, Enter, Space and a "button" announcement for free.' },
      { code: '<button type="button" aria-pressed="false">Rope</button>', note: 'A toggle button: screen readers announce "Rope, toggle button, not pressed." Update it to "true" from JavaScript when it\'s packed.' },
      { code: 'button:focus-visible { outline: 3px solid #1565c0; outline-offset: 2px; }', note: 'A strong, visible focus ring for keyboard users.' },
    ],
    uses: ['Every public website and app. About 1 in 6 people worldwide lives with a significant disability.', 'Meeting legal requirements for business and government sites in many countries.', 'Better search results: search engines read pages much like screen readers do.', 'Judging other people\'s products (this camp\'s weather check).'],
    when: ['From the very first line. Accessible HTML costs almost nothing up front; fixing it later costs a rebuild.', 'Every time you add an image, an input, a button, or choose a colour.'],
    whenNot: ['Don\'t add ARIA to "fix" a `<div>` button when a `<button>` would do. The div still won\'t work with the keyboard.', 'Don\'t write alt text that repeats the caption word for word, or stuffs in keywords. Screen reader users hear it all.', 'Don\'t trust automated checkers as the whole answer. They catch maybe a third of problems. Also try the page with the keyboard only, and with a screen reader.'],
    mistakes: [
      { wrong: '<img src="IMG_2041.jpg">', result: 'Screen reader: "IMG underscore 2041 dot jpg, image"', why: 'No alt text, so it read the file name. Add a meaningful `alt`, or `alt=""` if it\'s decoration.' },
      { wrong: 'button:focus { outline: none; }', result: '(keyboard users can no longer see where they are on the page)', why: 'Removing the focus ring strands keyboard users. Style it instead, ideally with `:focus-visible`.' },
      { wrong: '.hint { color: #aaaaaa; }  (on white)', result: '(a contrast ratio of about 2.3:1; many people can\'t read it)', why: 'Normal text needs at least 4.5:1. Use a darker grey such as `#595959` or `#767676`.' },
      { wrong: '<input placeholder="Email">  (no label)', result: 'Screen reader may say only "edit text"; the hint vanishes once you type', why: 'Placeholders are not labels. Add `<label for="email">Email</label>`.' },
    ],
    tips: ['The two-minute test: unplug the mouse (or ignore the touchpad) and use the page with Tab, Shift+Tab, Enter and Space only.', 'Chrome\'s devtools have a **Lighthouse** tab that scores accessibility, and the colour picker in the Styles pane shows the contrast ratio.', 'Write alt text as if describing the picture to a friend over the phone: short, specific, useful.'],
    related: ['page-structure', 'forms', 'html-attribute', 'events', 'devtools'],
    os: {
      linux: '**Try a screen reader:** GNOME includes **Orca**. Toggle it with **Super+Alt+S** (or Settings → Accessibility → Screen Reader).',
      mac: '**Try a screen reader:** **VoiceOver** is built in. Toggle it with **Cmd+F5** (on some keyboards, hold Fn or press the Touch ID button three times).',
      windows: '**Try a screen reader:** **Narrator** is built in: **Ctrl+Win+Enter** toggles it. Many blind users use **NVDA**, which is free.',
      chromeos: '**Try a screen reader:** **ChromeVox** is built in: **Ctrl+Alt+Z** toggles it.',
      phone: '**Try a screen reader:** iPhone: Settings → Accessibility → **VoiceOver**. Android: Settings → Accessibility → **TalkBack**. Swipe right to move to the next item and double-tap to activate. Turn it off the same way (practise that first).',
    },
  },
  devtools: {
    term: 'Browser devtools', stands: 'developer tools',
    short: 'The inspection panel built into every desktop browser: see and edit the live page, its CSS, errors and network traffic.',
    what: 'Every desktop browser has **developer tools** built in: a panel that shows how the page really works. You can inspect any element, see which CSS applies (and which lost), run JavaScript, read error messages, and watch every file the page downloads. It\'s the single most useful tool for web work, and it\'s free.',
    how: '**The panels you\'ll use** (names from Chrome; Firefox and Safari are very similar):\n• **Elements** (Firefox: Inspector): the live DOM tree. Click any element to see its CSS in the **Styles** pane (crossed-out lines lost the cascade; warning icons mark invalid values) and the **Computed** pane (final values plus the box-model diagram). You can edit HTML and CSS right there and see it instantly.\n• **Console**: red error messages from your JavaScript, with file and line number, and a prompt where you can type JavaScript against the live page.\n• **Network**: every file the page loads, with status codes (404 = file not found). Great for "why isn\'t my CSS loading?"\n• **Lighthouse** (Chrome): audits accessibility, performance and more.\n\n**Inspect mode:** click the arrow icon in the top-left of the devtools (or use the shortcut), then click anything on the page to jump to it in the Elements panel. Or right-click any part of a page and choose **Inspect**.\n\n**Everything you change in the devtools is temporary.** It lives in that tab\'s memory and disappears on reload. It\'s a sketchpad: try things there, then copy what works into your files.\n\nShortcuts differ by browser and computer; your platform\'s are in the box below.',
    usage: [
      { code: 'Right-click the heading → Inspect', out: '<h1>Camp III</h1>   (highlighted in the Elements panel)', note: 'The fastest way to find any element\'s HTML and CSS.' },
      { code: '> document.querySelectorAll(".item").length', out: '4', note: 'Typed in the Console: test a selector against the live page.' },
      { code: 'Uncaught TypeError: Cannot read properties of null (reading \'addEventListener\')   app.js:3', note: 'An error in the Console. Click `app.js:3` to jump to the line.' },
      { code: 'Styles pane:\n  #title { color: #b71c1c; }\n  h1     { color: blue; }   ← shown crossed out', note: 'The crossed-out declaration lost: the id selector is more specific.' },
    ],
    uses: ['Finding out why a style "doesn\'t work."', 'Reading JavaScript errors with exact line numbers.', 'Trying CSS changes live before writing them into your file.', 'Checking a page on phone sizes (device mode) and auditing accessibility.', 'Seeing what a site downloads, including whether it sends your data somewhere.'],
    when: ['Any time something on a page looks or behaves wrong. Open the devtools before guessing.', 'Whenever you write browser JavaScript: keep the Console open to catch errors.'],
    whenNot: ['Don\'t treat devtools edits as saved. Reload and they\'re gone.', 'Never paste code into the Console because a stranger, website or "support agent" told you to. Scammers use this to steal accounts; some sites print a big warning in the Console for exactly this reason.', 'Don\'t judge a phone layout only in device mode. It\'s close, but check on a real phone too.'],
    mistakes: [
      { prose: 'Fixing a bug in the Elements panel, reloading, and the bug is back.', why: 'Devtools edits aren\'t saved to your file. Copy the working change into your code.' },
      { prose: 'Ignoring the red number in the corner of the devtools.', why: 'That\'s your error count. Open the Console and read the first error top to bottom; the rest are often caused by it.' },
      { prose: 'Looking at view-source and not finding the element your script added.', why: 'View-source shows the original file. The Elements panel shows the live DOM, including JavaScript\'s changes.' },
    ],
    tips: ['Keep the devtools docked to the side while you build, Console visible.', 'Hover over an element in the Elements panel to highlight it (with its padding and margin) on the page.', 'In the Styles pane, click a colour swatch to open the picker; Chrome shows the contrast ratio right there.'],
    related: ['dom', 'css', 'box-model', 'accessibility', 'responsive-design'],
    os: {
      linux: '**Chrome / Chromium:** **F12** or **Ctrl+Shift+I** opens the devtools. **Ctrl+Shift+J** jumps to the Console. **Ctrl+Shift+C** starts inspect mode.\n**Firefox:** **F12** or **Ctrl+Shift+I**. **Ctrl+Shift+K** for the Console, **Ctrl+Shift+C** for the inspector.\nOr right-click anything → **Inspect**. Safari doesn\'t exist on Linux.',
      mac: '**Chrome:** **Cmd+Option+I** opens the devtools. **Cmd+Option+J** jumps to the Console. **Cmd+Shift+C** starts inspect mode.\n**Firefox:** **Cmd+Option+I**. **Cmd+Option+K** for the Console, **Cmd+Option+C** for the inspector.\n**Safari:** turn it on first: Safari → Settings → Advanced → tick **"Show features for web developers"** (older versions: "Show Develop menu in menu bar"). Then **Cmd+Option+I** opens the Web Inspector and **Cmd+Option+C** opens the Console.\nOr right-click anything → **Inspect** (Safari: **Inspect Element**).',
      windows: '**Chrome / Edge:** **F12** or **Ctrl+Shift+I** opens the devtools. **Ctrl+Shift+J** jumps to the Console. **Ctrl+Shift+C** starts inspect mode.\n**Firefox:** **F12** or **Ctrl+Shift+I**. **Ctrl+Shift+K** for the Console, **Ctrl+Shift+C** for the inspector.\nOr right-click anything → **Inspect**. (Use your Windows browser, even for pages you build in WSL.)',
      chromeos: '**Chrome:** **Ctrl+Shift+I** opens the devtools (Chromebook keyboards usually have no F12). **Ctrl+Shift+J** jumps to the Console; **Ctrl+Shift+C** starts inspect mode. Or right-click (two-finger tap) → **Inspect**.',
      phone: 'Phone browsers have **no built-in devtools panel**. What you can do:\n• **Read a page\'s HTML:** in Chrome for Android, type `view-source:` before the address.\n• **iPhone + a Mac:** on the iPhone, Settings → Safari → Advanced → turn on **Web Inspector**. Connect it by cable, then on the Mac\'s Safari open the **Develop** menu and pick your iPhone to inspect its open page.\n• **Android + a computer:** turn on **USB debugging** in Developer options, connect by cable, open Chrome on the computer and go to `chrome://inspect`.\n• **In this game:** the live preview and the Sherpa\'s checklist do the inspecting for you. For real web work, a computer with devtools is worth it.',
    },
  },
}
